/**
 * Jinx Hatter + Leviathan: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Hatter
 * Wiki: https://wiki.bloodontheclocktower.com/Leviathan
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong, type Script } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import type { Command } from '#lib/core/engine/index.ts';
import { castWith } from '#lib/core/model/fixtures.test-support.ts';
import { createdTooLate, ownJinxRules } from '#lib/core/rules/jinxes.ts';

const scriptOf = (ids: string[]): Script => ({
	meta: { name: 'Jinxed' },
	entries: ids.map((id) => ({ kind: 'official' as const, id }))
});

describe('Hatter + Leviathan jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'hatter', 'leviathan');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('hatter')?.name).toBe('Hatter');
		expect(data.byId.get('leviathan')?.name).toBe('Leviathan');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['hatter', 'leviathan'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['hatter'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['leviathan'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: the Leviathan can't enter play after day 5, so once day 5
	// is over the Hatter's tea party can't make anyone the Leviathan. The Hatter's character
	// picker leaves it out.
	describe('the Leviathan is not offered after day 5', () => {
		const ids = ['hatter', 'leviathan', 'imp', 'chef', 'empath', 'poisoner'];
		const cast = castWith({ script: scriptOf(ids) });
		const players = ['hatter', 'imp', 'chef', 'empath', 'poisoner', 'washerwoman', 'butler'];
		const newDay: Command = { type: 'NewDay' };

		it("is data in the Hatter's rules", () => {
			expect(ownJinxRules({ script: scriptOf(ids) }, 'hatter', 'leviathan')).toEqual({
				notCreatedAfterDay: 5
			});
		});

		it('is offered up to the night after day 4, and not after day 5', () => {
			const four = cast(players, newDay, newDay, newDay, newDay);
			expect(createdTooLate(four.game, 'hatter', four.ctx.characters)).toEqual([]);
			const five = cast(players, newDay, newDay, newDay, newDay, newDay);
			expect(createdTooLate(five.game, 'hatter', five.ctx.characters)).toEqual(['leviathan']);
		});

		it('applies only while both are on the script', () => {
			const script = scriptOf(['hatter', 'imp', 'chef', 'empath', 'poisoner']);
			const five = castWith({ script })(players, newDay, newDay, newDay, newDay, newDay);
			expect(createdTooLate(five.game, 'hatter', five.ctx.characters)).toEqual([]);
		});
	});
});
